use futures::future::{self, TryFutureExt};

let pending = future::try_join(fetch_a(), fetch_b())    // composed as values
    .map_ok(|(a, b)| merge(a, b));
let merged = block_on(pending)?;                        // drive it to completion

use std::sync::mpsc::channel;

